import pyomo.environ as pyo

DATA = {
    # "Job 0 has 5 operations with processing times of 7, 9, 8, 3, and 9 hours."
    "jobs": [0, 1, 2],
    "proc_times": {
        0: [7, 9, 8, 3, 9],          # Job 0: 5 operations
        1: [1, 3, 4, 1, 2, 9],       # Job 1: 6 operations
        2: [9, 3, 1, 3, 3, 3, 5],    # Job 2: 7 operations
    },
    # Machine required by each operation (j, o). Each job visits machines in
    # a fixed cyclic order so that operations from different jobs share machines
    # and must be sequenced ("Operations from different jobs that require the
    # same machine must be scheduled in a specific order to avoid overlapping.").
    "machine": {
        (0, 0): 0, (0, 1): 1, (0, 2): 2, (0, 3): 3, (0, 4): 4,
        (1, 0): 0, (1, 1): 1, (1, 2): 2, (1, 3): 3, (1, 4): 4, (1, 5): 0,
        (2, 0): 0, (2, 1): 1, (2, 2): 2, (2, 3): 3, (2, 4): 4, (2, 5): 0, (2, 6): 1,
    },
    # "A large constant (100,000) is used in the constraints..."
    "big_m": 100000,
}


def build_model(data=None):
    d = data or DATA
    jobs = list(d["jobs"])
    proc = d["proc_times"]
    machine = d["machine"]
    M = d["big_m"]

    # Ordered operation list per job and the flat set of all operations.
    ops = {}
    for j in jobs:
        ops[j] = list(range(len(proc[j])))
    all_ops = [(j, o) for j in jobs for o in ops[j]]

    # Pairs of distinct operations that share a machine (disjunctive pairs).
    machine_ops = {}
    for (j, o) in all_ops:
        machine_ops.setdefault(machine[(j, o)], []).append((j, o))
    pairs = []
    for m, lst in machine_ops.items():
        for a in range(len(lst)):
            for b in range(a + 1, len(lst)):
                pairs.append((lst[a], lst[b]))

    model = pyo.ConcreteModel()

    model.JOBS = pyo.Set(initialize=jobs, ordered=True)
    model.ALL_OPS = pyo.Set(initialize=all_ops, dimen=2, ordered=True)
    model.PAIRS = pyo.Set(initialize=pairs, dimen=4, ordered=True)

    # Start times of every operation (non-negative).
    model.s = pyo.Var(model.ALL_OPS, within=pyo.NonNegativeReals)

    # Makespan.
    model.Cmax = pyo.Var(within=pyo.NonNegativeReals)

    # Sequencing binaries for shared-machine operation pairs.
    model.y = pyo.Var(model.PAIRS, within=pyo.Binary)

    def _ptime(j, o):
        return proc[j][o]

    # Precedence: operation o+1 of a job starts after operation o finishes.
    def precedence_rule(m, j, o):
        if o + 1 < len(proc[j]):
            return m.s[j, o + 1] >= m.s[j, o] + _ptime(j, o)
        return pyo.Constraint.Skip

    model.precedence = pyo.Constraint(model.ALL_OPS, rule=precedence_rule)

    # Machine capacity: for each shared-machine pair, one must precede the other.
    def machine_rule1(m, j1, o1, j2, o2):
        return (m.s[j1, o1] + _ptime(j1, o1)
                <= m.s[j2, o2] + M * (1 - m.y[j1, o1, j2, o2]))

    def machine_rule2(m, j1, o1, j2, o2):
        return (m.s[j2, o2] + _ptime(j2, o2)
                <= m.s[j1, o1] + M * m.y[j1, o1, j2, o2])

    model.machine_order_a = pyo.Constraint(model.PAIRS, rule=machine_rule1)
    model.machine_order_b = pyo.Constraint(model.PAIRS, rule=machine_rule2)

    # Makespan must be at least the completion time of every operation.
    def makespan_rule(m, j, o):
        return m.Cmax >= m.s[j, o] + _ptime(j, o)

    model.makespan = pyo.Constraint(model.ALL_OPS, rule=makespan_rule)

    model.obj = pyo.Objective(expr=model.Cmax, sense=pyo.minimize)

    return model


