import pyomo.environ as pyo

DATA = {
    "processing": {
        0: [7, 9, 8, 3, 9],
        1: [1, 3, 4, 1, 2, 9],
        2: [9, 3, 1, 3, 3, 3, 5],
    },
    "num_jobs": 3,
    "BIG_M": 100000,
}


def build_model(data=None):
    d = data or DATA
    proc = d["processing"]

    # Build ordered operation list: (job, step, duration)
    op_list = []
    for j in range(d["num_jobs"]):
        for o, dur in enumerate(proc[j]):
            op_list.append((j, o, dur))
    n_ops = len(op_list)

    # Global op index -> (job, step), duration
    op_job = {}
    op_step = {}
    op_dur = {}
    for idx, (j, o, dur) in enumerate(op_list, start=1):
        op_job[idx] = j
        op_step[idx] = o
        op_dur[idx] = dur

    # Precedence pairs within job: (successor, predecessor)
    prec_pairs = []
    for idx in range(1, n_ops + 1):
        j = op_job[idx]
        o = op_step[idx]
        if o > 0:
            for k in range(1, n_ops + 1):
                if op_job[k] == j and op_step[k] == o - 1:
                    prec_pairs.append((idx, k))
                    break

    # Disjunctive pairs for shared machine: all unequal ops (single shared resource)
    pairs = []
    for n in range(1, n_ops + 1):
        for m in range(n + 1, n_ops + 1):
            pairs.append((n, m))

    model = pyo.ConcreteModel()

    # ---- Sets ----
    model.OPS = pyo.Set(initialize=list(range(1, n_ops + 1)), ordered=True)
    model.PRED_PAIRS = pyo.Set(dimen=2, initialize=prec_pairs, ordered=True)
    model.DISJ = pyo.Set(dimen=2, initialize=pairs, ordered=True)

    # ---- Variables ----
    model.s = pyo.Var(model.OPS, domain=pyo.NonNegativeReals)
    model.Cmax = pyo.Var(domain=pyo.NonNegativeReals)
    model.y = pyo.Var(model.DISJ, domain=pyo.Binary)

    # ---- Objective ----
    model.obj = pyo.Objective(expr=model.Cmax, sense=pyo.minimize)

    # ---- Precedence constraints within each job ----
    def _prec_rule(m, succ, pred):
        return m.s[succ] >= m.s[pred] + op_dur[pred]

    model.precedence = pyo.Constraint(model.PRED_PAIRS, rule=_prec_rule)

    # ---- Disjunctive machine capacity constraints ----
    def _disj_first(m, n, k):
        return m.s[k] >= m.s[n] + op_dur[n] - d["BIG_M"] * (1.0 - m.y[n, k])

    def _disj_second(m, n, k):
        return m.s[n] >= m.s[k] + op_dur[k] - d["BIG_M"] * m.y[n, k]

    model.disj_first = pyo.Constraint(model.DISJ, rule=_disj_first)
    model.disj_second = pyo.Constraint(model.DISJ, rule=_disj_second)

    # ---- Makespan constraints ----
    def _makespan_rule(m, i):
        return m.Cmax >= m.s[i] + op_dur[i]

    model.makespan = pyo.Constraint(model.OPS, rule=_makespan_rule)

    return model


